@page "/apply"
@rendermode InteractiveServer
@using sv_9ab34aed323c4f8191316c954cb808e2.Services
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<h1>Job Application</h1>

<!-- Step Indicator Bar -->
<div class="step-indicator">
    @for (int i = 0; i < _stepNames.Length; i++)
    {
        var stepIndex = i;
        var stepClass = GetStepClass(stepIndex);
        <div class="step @stepClass" @onclick="() => GoToStep(stepIndex)">
            <div class="step-circle">
                @if (stepIndex < _currentStep)
                {
                    <span>&#10003;</span>
                }
                else
                {
                    <span>@(stepIndex + 1)</span>
                }
            </div>
            <div class="step-label">@_stepNames[stepIndex]</div>
        </div>
        @if (i < _stepNames.Length - 1)
        {
            <div class="step-connector @(stepIndex < _currentStep ? "completed" : "")"></div>
        }
    }
</div>

@if (!string.IsNullOrEmpty(_errorMessage))
{
    <div class="alert alert-danger mt-3">@_errorMessage</div>
}

<!-- Step 1: Personal Info -->
@if (_currentStep == 0)
{
    <div class="form-section">
        <h3>Personal Information</h3>
        <div class="mb-3">
            <label class="form-label">Full Name *</label>
            <input type="text" class="form-control" @bind="_fullName" />
        </div>
        <div class="mb-3">
            <label class="form-label">Email *</label>
            <input type="email" class="form-control" @bind="_email" />
        </div>
        <div class="mb-3">
            <label class="form-label">Phone *</label>
            <input type="tel" class="form-control" @bind="_phone" />
        </div>
        <div class="mb-3">
            <label class="form-label">Address *</label>
            <input type="text" class="form-control" @bind="_address" />
        </div>
        <div class="nav-buttons">
            <button class="btn btn-primary" @onclick="NextFromPersonalInfo" disabled="@_isValidating">
                @if (_isValidating)
                {
                    <span>Validating...</span>
                }
                else
                {
                    <span>Next</span>
                }
            </button>
        </div>
    </div>
}

<!-- Step 2: Work History -->
@if (_currentStep == 1)
{
    <div class="form-section">
        <h3>Work History</h3>
        @for (int i = 0; i < _workEntries.Count; i++)
        {
            var index = i;
            <div class="card mb-3 p-3">
                <h5>Position @(index + 1)</h5>
                <div class="mb-2">
                    <label class="form-label">Company *</label>
                    <input type="text" class="form-control" value="@_workEntries[index].Company"
                        @onchange="e => _workEntries[index].Company = e.Value?.ToString() ?? string.Empty" />
                </div>
                <div class="mb-2">
                    <label class="form-label">Job Title *</label>
                    <input type="text" class="form-control" value="@_workEntries[index].Title"
                        @onchange="e => _workEntries[index].Title = e.Value?.ToString() ?? string.Empty" />
                </div>
                <div class="row mb-2">
                    <div class="col-md-4">
                        <label class="form-label">Start Date *</label>
                        <input type="date" class="form-control" value="@_workEntries[index].StartDate?.ToString("yyyy-MM-dd")"
                            @onchange="e => _workEntries[index].StartDate = string.IsNullOrEmpty(e.Value?.ToString()) ? null : DateTime.Parse(e.Value.ToString()!)" />
                    </div>
                    <div class="col-md-4">
                        <label class="form-label">End Date</label>
                        <input type="date" class="form-control" value="@_workEntries[index].EndDate?.ToString("yyyy-MM-dd")"
                            @onchange="e => _workEntries[index].EndDate = string.IsNullOrEmpty(e.Value?.ToString()) ? null : DateTime.Parse(e.Value.ToString()!)"
                            disabled="@_workEntries[index].IsCurrent" />
                    </div>
                    <div class="col-md-4 d-flex align-items-end">
                        <div class="form-check">
                            <input type="checkbox" class="form-check-input" checked="@_workEntries[index].IsCurrent"
                                @onchange="e => _workEntries[index].IsCurrent = (bool)(e.Value ?? false)" />
                            <label class="form-check-label">Currently working here</label>
                        </div>
                    </div>
                </div>
                <div class="mb-2">
                    <label class="form-label">Description</label>
                    <textarea class="form-control" rows="3" @onchange="e => _workEntries[index].Description = e.Value?.ToString() ?? string.Empty">@_workEntries[index].Description</textarea>
                </div>
                @if (_workEntries.Count > 1)
                {
                    <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveWorkEntry(index)">Remove</button>
                }
            </div>
        }
        <button class="btn btn-outline-secondary mb-3" @onclick="AddWorkEntry">+ Add Another Position</button>
        <div class="nav-buttons">
            <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
            <button class="btn btn-primary" @onclick="NextFromWorkHistory">Next</button>
        </div>
    </div>
}

<!-- Step 3: References -->
@if (_currentStep == 2)
{
    <div class="form-section">
        <h3>References</h3>
        @for (int i = 0; i < _references.Count; i++)
        {
