            <textarea class="form-control" rows="12" maxlength="2000"
                @bind="_coverLetter" @bind:event="oninput"></textarea>
            <div class="form-text">@_coverLetter.Length / 2000 characters</div>
        </div>
        <div class="nav-buttons">
            <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
            <button class="btn btn-primary" @onclick="NextStep">Next</button>
        </div>
    </div>
}

<!-- Step 5: Review & Submit -->
@if (_currentStep == 4)
{
    @if (_isSubmitted)
    {
        <div class="form-section text-center">
            <h3 class="text-success">&#10003; Application Submitted!</h3>
            <p class="fs-5">Your application ID is: <strong>@_applicationId</strong></p>
            <p>Thank you for applying. We will be in touch soon.</p>
        </div>
    }
    else
    {
        <div class="form-section">
            <h3>Review & Submit</h3>

            <!-- Personal Info Summary -->
            <div class="review-section">
                <div class="d-flex justify-content-between align-items-center">
                    <h5>Personal Information</h5>
                    <a href="javascript:void(0)" @onclick='() => GoToStep(0)'>Edit</a>
                </div>
                <dl class="row mb-0">
                    <dt class="col-sm-3">Name</dt><dd class="col-sm-9">@_fullName</dd>
                    <dt class="col-sm-3">Email</dt><dd class="col-sm-9">@_email</dd>
                    <dt class="col-sm-3">Phone</dt><dd class="col-sm-9">@_phone</dd>
                    <dt class="col-sm-3">Address</dt><dd class="col-sm-9">@_address</dd>
                </dl>
            </div>

            <!-- Work History Summary -->
            <div class="review-section">
                <div class="d-flex justify-content-between align-items-center">
                    <h5>Work History</h5>
                    <a href="javascript:void(0)" @onclick='() => GoToStep(1)'>Edit</a>
                </div>
                @foreach (var entry in _workEntries)
                {
                    <div class="mb-2 ps-3 border-start">
                        <strong>@entry.Title</strong> at @entry.Company<br />
                        <small>@entry.StartDate?.ToString("MMM yyyy") &ndash; @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))</small>
                        @if (!string.IsNullOrWhiteSpace(entry.Description))
                        {
                            <p class="mb-0 mt-1 text-muted">@entry.Description</p>
                        }
                    </div>
                }
            </div>

            <!-- References Summary -->
            <div class="review-section">
                <div class="d-flex justify-content-between align-items-center">
                    <h5>References</h5>
                    <a href="javascript:void(0)" @onclick='() => GoToStep(2)'>Edit</a>
                </div>
                @foreach (var r in _references)
                {
                    <div class="mb-2 ps-3 border-start">
                        <strong>@r.Name</strong> (@r.Relationship)<br />
                        <small>@r.Email &bull; @r.Phone</small>
                    </div>
                }
            </div>

            <!-- Cover Letter Summary -->
            <div class="review-section">
                <div class="d-flex justify-content-between align-items-center">
                    <h5>Cover Letter</h5>
                    <a href="javascript:void(0)" @onclick='() => GoToStep(3)'>Edit</a>
                </div>
                <p class="text-muted" style="white-space: pre-wrap;">@_coverLetter</p>
            </div>

